"use client"

import { useEffect, useState } from "react"
import { motion, AnimatePresence } from "framer-motion"
import { Award, Bell, BookOpen, Calendar, CheckCircle2, Edit, Eye, GraduationCap, Home, Mail, Menu, PanelLeft, Plus, Save, Trash2, UserPlus, X, FileText } from 'lucide-react'

import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Progress } from "@/components/ui/progress"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { Textarea } from "@/components/ui/textarea"
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Checkbox } from "@/components/ui/checkbox"
import { cn } from "@/lib/utils"

// Importar APIs da aplicação
import {
  dashboardApi,
  teachersApi,
  subjectsApi,
  notesApi,
  profileApi,
  authApi,
  studentApi,
  type Professor,
  type Materia,
  type Anotacao,
  type Usuario,
  type Trabalho,
  type Teacher,
  type Subject,
  type Note,
  type Student,
  mapProfessorToTeacher,
  mapMateriaToSubject
} from "@/lib/api"

const sidebarItems = [
  { title: "Painel", icon: <Home className="h-5 w-5" />, value: "painel" },
  { title: "Aulas", icon: <BookOpen className="h-5 w-5" />, value: "aulas" },
  { title: "Professores", icon: <UserPlus className="h-5 w-5" />, value: "professores" },
  { title: "Anotações", icon: <FileText className="h-5 w-5" />, value: "anotacoes" },
  { title: "Perfil", icon: <GraduationCap className="h-5 w-5" />, value: "perfil" },
]

const COLORS = [
  { label: "Azul", value: "bg-blue-500" },
  { label: "Verde", value: "bg-green-500" },
  { label: "Roxo", value: "bg-purple-500" },
  { label: "Rosa", value: "bg-pink-500" },
  { label: "Amarelo", value: "bg-yellow-500" },
  { label: "Vermelho", value: "bg-red-500" },
]

export default function DashboardPage() {
  const [activeTab, setActiveTab] = useState("painel")
  const [sidebarOpen, setSidebarOpen] = useState(true)

  const [teachers, setTeachers] = useState<Teacher[]>([])
  const [subjects, setSubjects] = useState<Subject[]>([])
  const [notes, setNotes] = useState<Note[]>([])
  const [student, setStudent] = useState<Student | null>(null)
  const [stats, setStats] = useState<any>(null)
  const [loading, setLoading] = useState(true)

  // Modals
  const [teacherModal, setTeacherModal] = useState(false)
  const [subjectModal, setSubjectModal] = useState(false)
  const [noteModal, setNoteModal] = useState(false)
  const [editingTeacher, setEditingTeacher] = useState<Teacher | null>(null)
  const [editingSubject, setEditingSubject] = useState<Subject | null>(null)
  const [editingNote, setEditingNote] = useState<Note | null>(null)

  // Form states
  const [teacherForm, setTeacherForm] = useState({ nome: "", email: "", disciplina: "" })
  const [subjectForm, setSubjectForm] = useState<{
    nome: string
    cor: string
    professorId: string
    notaProva: string
    trabalhos: Array<{
      titulo: string
      descricao: string
      dataEntrega: string
      concluido: boolean
    }>
  }>({ 
    nome: "", 
    cor: "bg-blue-500", 
    professorId: "", 
    notaProva: "0",
    trabalhos: [] 
  })
  const [noteForm, setNoteForm] = useState({ titulo: "", conteudo: "", materiaId: "none" })
  const [profileForm, setProfileForm] = useState({ nome: "", email: "", telefone: "" })
  const [profileEditing, setProfileEditing] = useState(false)

  useEffect(() => {
    if (!authApi.isAuthenticated()) {
      window.location.href = '/login'
      return
    }
    loadData()
  }, [])

  const loadData = async () => {
    try {
      setLoading(true)
      
      const [dashboard, professores, materias, anotacoes, perfil] = await Promise.all([
        dashboardApi.getDashboard(),
        teachersApi.getAll(),
        subjectsApi.getAll(),
        notesApi.getAll(),
        profileApi.get()
      ])

      const mappedTeachers = professores.map((p: Professor) => mapProfessorToTeacher({
        id: p.id,
        nome: p.nome,
        email: p.email,
        disciplina: p.disciplina || ""
      }))

      setTeachers(mappedTeachers)
      setSubjects(materias.map((m: Materia) => ({
        id: m.id.toString(),
        name: m.nome,
        teacher: professores.find((p: Professor) => p.id === m.professorId)?.nome || "N/A",
        teacherId: m.professorId.toString(),
        totalClasses: m.aulas?.length || 0,
        attendedClasses: m.aulas?.filter((a: any) => a.presente).length || 0,
        assignments: m.trabalhos?.length || 0,
        completedAssignments: m.trabalhos?.filter((t: any) => t.concluido).length || 0,
        testGrade: m.notaProva || 0,
        color: m.cor
      })))
      setNotes(anotacoes.map((n: Anotacao) => ({
        id: n.id.toString(),
        title: n.titulo,
        subject: materias.find((m: Materia) => m.id === n.materiaId)?.nome || "Geral",
        subjectId: n.materiaId?.toString() || "",
        content: n.conteudo,
        date: new Date(n.dataCriacao).toLocaleDateString('pt-BR'),
        color: "bg-blue-50",
        createdAt: n.dataCriacao,
        updatedAt: n.dataAtualizacao
      })))
      
      const studentData = await studentApi.getProfile()
      setStudent(studentData)
      setProfileForm({ 
        nome: perfil.nome, 
        email: perfil.email, 
        telefone: perfil.telefone || "" 
      })

      if (dashboard) {
        setStats(dashboard.metricasProgresso)
      }
    } catch (error) {
      console.error("Erro ao carregar dados:", error)
    } finally {
      setLoading(false)
    }
  }

  const calculateScore = () => {
    if (stats) return Math.round(stats.pontuacaoGeral)
    return 0
  }

  // ============= TEACHER CRUD =============
  const openTeacherModal = (teacher: Teacher | null = null) => {
    if (teacher) {
      setEditingTeacher(teacher)
      setTeacherForm({ 
        nome: teacher.name, 
        email: teacher.email, 
        disciplina: teacher.subject 
      })
    } else {
      setEditingTeacher(null)
      setTeacherForm({ nome: "", email: "", disciplina: "" })
    }
    setTeacherModal(true)
  }

  const saveTeacher = async () => {
    try {
      if (!teacherForm.nome || !teacherForm.email) {
        alert("Nome e email são obrigatórios")
        return
      }

      if (editingTeacher) {
        await teachersApi.update(parseInt(editingTeacher.id), {
          nome: teacherForm.nome,
          email: teacherForm.email,
          disciplina: teacherForm.disciplina
        })
      } else {
        await teachersApi.create({
          nome: teacherForm.nome,
          email: teacherForm.email,
          disciplina: teacherForm.disciplina
        })
      }

      await loadData()
      setTeacherModal(false)
      setTeacherForm({ nome: "", email: "", disciplina: "" })
    } catch (error) {
      console.error("Erro ao salvar professor:", error)
      alert("Erro ao salvar professor")
    }
  }

  const deleteTeacher = async (id: string) => {
    if (!confirm("Deseja realmente excluir este professor?")) return

    try {
      await teachersApi.delete(parseInt(id))
      await loadData()
    } catch (error) {
      console.error("Erro ao deletar professor:", error)
      alert("Erro ao deletar professor")
    }
  }

  // ============= SUBJECT CRUD =============
  const openSubjectModal = (subject: Subject | null = null) => {
    if (subject) {
      setEditingSubject(subject)
      setSubjectForm({
        nome: subject.name,
        cor: subject.color,
        professorId: subject.teacherId,
        notaProva: subject.testGrade.toString(),
        trabalhos: []
      })
    } else {
      setEditingSubject(null)
      setSubjectForm({ 
        nome: "", 
        cor: "bg-blue-500", 
        professorId: "", 
        notaProva: "0",
        trabalhos: []
      })
    }
    setSubjectModal(true)
  }

  const addTrabalho = () => {
    setSubjectForm(prev => ({
      ...prev,
      trabalhos: [
        ...prev.trabalhos,
        {
          titulo: "",
          descricao: "",
          dataEntrega: new Date().toISOString().split('T')[0],
          concluido: false
        }
      ]
    }))
  }

  const removeTrabalho = (index: number) => {
    setSubjectForm(prev => ({
      ...prev,
      trabalhos: prev.trabalhos.filter((_, i) => i !== index)
    }))
  }

  const updateTrabalho = (index: number, field: string, value: any) => {
    setSubjectForm(prev => ({
      ...prev,
      trabalhos: prev.trabalhos.map((t, i) => 
        i === index ? { ...t, [field]: value } : t
      )
    }))
  }

  const saveSubject = async () => {
    try {
      if (!subjectForm.nome || !subjectForm.professorId) {
        alert("Nome da matéria e professor são obrigatórios")
        return
      }

      const payload = {
        nome: subjectForm.nome,
        cor: subjectForm.cor,
        professorId: parseInt(subjectForm.professorId),
        notaProva: parseFloat(subjectForm.notaProva) || 0
      }

      let materiaId: number

      if (editingSubject) {
        await subjectsApi.update(parseInt(editingSubject.id), payload)
        materiaId = parseInt(editingSubject.id)

        // Buscar matéria atualizada para pegar trabalhos existentes
        const materiaAtualizada = await subjectsApi.getById(materiaId)
        if (materiaAtualizada.trabalhos) {
          for (const trabalho of materiaAtualizada.trabalhos) {
            await subjectsApi.deleteTrabalho(materiaId, trabalho.id)
          }
        }
      } else {
        const result = await subjectsApi.create(payload)
        materiaId = result.id
      }

      // Criar trabalhos novos
      for (const trabalho of subjectForm.trabalhos) {
        if (trabalho.titulo.trim()) {
          await subjectsApi.addTrabalho(materiaId, {
            titulo: trabalho.titulo,
            descricao: trabalho.descricao || undefined,
            dataEntrega: new Date(trabalho.dataEntrega).toISOString(),
            concluido: trabalho.concluido
          })
        }
      }

      await loadData()
      setSubjectModal(false)
      setSubjectForm({ nome: "", cor: "bg-blue-500", professorId: "", notaProva: "0", trabalhos: [] })
    } catch (error) {
      console.error("Erro ao salvar matéria:", error)
      alert("Erro ao salvar matéria: " + (error instanceof Error ? error.message : "Erro desconhecido"))
    }
  }

  const deleteSubject = async (id: string) => {
    if (!confirm("Deseja realmente excluir esta matéria?")) return

    try {
      await subjectsApi.delete(parseInt(id))
      await loadData()
    } catch (error) {
      console.error("Erro ao deletar matéria:", error)
      alert("Erro ao deletar matéria")
    }
  }

  // ============= NOTE CRUD =============
  const openNoteModal = (note: Note | null = null) => {
    if (note) {
      setEditingNote(note)
      setNoteForm({ 
        titulo: note.title, 
        conteudo: note.content, 
        materiaId: note.subjectId || "none" 
      })
    } else {
      setEditingNote(null)
      setNoteForm({ titulo: "", conteudo: "", materiaId: "none" })
    }
    setNoteModal(true)
  }

  const saveNote = async () => {
    try {
      if (!noteForm.titulo || !noteForm.conteudo) {
        alert("Título e conteúdo são obrigatórios")
        return
      }

      const payload = {
        titulo: noteForm.titulo,
        conteudo: noteForm.conteudo,
        materiaId: noteForm.materiaId === "none" ? undefined : parseInt(noteForm.materiaId)
      }

      if (editingNote) {
        await notesApi.update(parseInt(editingNote.id), payload)
      } else {
        await notesApi.create(payload)
      }

      await loadData()
      setNoteModal(false)
      setNoteForm({ titulo: "", conteudo: "", materiaId: "none" })
    } catch (error) {
      console.error("Erro ao salvar anotação:", error)
      alert("Erro ao salvar anotação")
    }
  }

  const deleteNote = async (id: string) => {
    if (!confirm("Deseja realmente excluir esta anotação?")) return

    try {
      await notesApi.delete(parseInt(id))
      await loadData()
    } catch (error) {
      console.error("Erro ao deletar anotação:", error)
      alert("Erro ao deletar anotação")
    }
  }

  // ============= PROFILE =============
  const saveProfile = async () => {
    try {
      await profileApi.update({
        nome: profileForm.nome,
        telefone: profileForm.telefone || undefined
      })

      await loadData()
      setProfileEditing(false)
      alert("Perfil atualizado com sucesso!")
    } catch (error) {
      console.error("Erro ao salvar perfil:", error)
      alert("Erro ao salvar perfil")
    }
  }

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center">
        <div className="text-center space-y-4">
          <GraduationCap className="h-16 w-16 mx-auto animate-pulse text-primary" />
          <p className="text-lg text-muted-foreground">Carregando dashboard...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="flex h-screen bg-gray-50">
      {/* Sidebar */}
      <aside className={cn(
        "w-60 bg-white border-r border-gray-200 flex flex-col transition-all",
        !sidebarOpen && "w-0 overflow-hidden"
      )}>
        <div className="p-4 border-b">
          <div className="flex items-center gap-2">
            <div className="w-10 h-10 rounded-lg bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center">
              <GraduationCap className="h-6 w-6 text-white" />
            </div>
            <div>
              <h1 className="font-semibold text-lg">Zoombi</h1>
              <p className="text-xs text-gray-500">Organize seus estudos</p>
            </div>
          </div>
        </div>

        <div className="p-3 flex-1">
          <Input placeholder="Buscar..." className="mb-4" />
          <nav className="space-y-1">
            {sidebarItems.map((item) => (
              <button
                key={item.value}
                onClick={() => setActiveTab(item.value)}
                className={cn(
                  "w-full flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors",
                  activeTab === item.value
                    ? "bg-gray-100 text-gray-900"
                    : "text-gray-600 hover:bg-gray-50"
                )}
              >
                {item.icon}
                <span>{item.title}</span>
              </button>
            ))}
          </nav>
        </div>

        <div className="p-3 border-t">
          <button className="w-full flex items-center gap-3 px-3 py-2 rounded-lg hover:bg-gray-50">
            <Avatar className="h-8 w-8">
              <AvatarFallback>{student?.name?.charAt(0) || "E"}</AvatarFallback>
            </Avatar>
            <span className="text-sm font-medium">{student?.name || "Estudante"}</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col overflow-hidden">
        {/* Header */}
        <header className="h-16 bg-white border-b px-6 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <Button variant="ghost" size="icon" onClick={() => setSidebarOpen(!sidebarOpen)}>
              <Menu className="h-5 w-5" />
            </Button>
            <h2 className="text-xl font-semibold">Olá, {student?.name || "Estudante"}!</h2>
          </div>
          
          <div className="flex items-center gap-3">
            <Button variant="ghost" size="icon">
              <Calendar className="h-5 w-5" />
            </Button>
            <Button variant="ghost" size="icon" className="relative">
              <Bell className="h-5 w-5" />
              <span className="absolute top-1 right-1 h-4 w-4 bg-red-500 rounded-full text-[10px] text-white flex items-center justify-center">
                3
              </span>
            </Button>
            <Avatar className="h-9 w-9">
              <AvatarFallback>{student?.name?.charAt(0) || "E"}</AvatarFallback>
            </Avatar>
          </div>
        </header>

        {/* Content */}
        <main className="flex-1 overflow-y-auto">
          <div className="max-w-7xl mx-auto p-6">
            <Tabs value={activeTab} onValueChange={setActiveTab}>
              <TabsList className="bg-gray-100 p-1 rounded-lg mb-6">
                <TabsTrigger value="painel" className="rounded-md">Painel</TabsTrigger>
                <TabsTrigger value="aulas" className="rounded-md">Aulas</TabsTrigger>
                <TabsTrigger value="professores" className="rounded-md">Professores</TabsTrigger>
                <TabsTrigger value="anotacoes" className="rounded-md">Anotações</TabsTrigger>
                <TabsTrigger value="perfil" className="rounded-md">Perfil</TabsTrigger>
              </TabsList>

              {/* PAINEL */}
              <TabsContent value="painel" className="space-y-6 mt-0">
                <div className="bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 rounded-2xl p-8 text-white">
                  <Badge className="bg-white/20 mb-3">Seu Progresso</Badge>
                  <h2 className="text-3xl font-bold mb-2">Continue assim!</h2>
                  <p className="text-white/90">Você está no caminho certo. Continue dedicado aos seus estudos e alcance seus objetivos.</p>
                </div>

                <div>
                  <h3 className="text-2xl font-bold mb-4">Métricas de Progresso</h3>
                  <div className="grid md:grid-cols-3 gap-4">
                    <Card>
                      <CardHeader className="pb-3">
                        <div className="flex items-center justify-between">
                          <CardTitle className="text-lg">Frequência</CardTitle>
                          <Calendar className="h-5 w-5 text-blue-500" />
                        </div>
                      </CardHeader>
                      <CardContent>
                        <div className="space-y-2">
                          <div className="flex items-baseline gap-2">
                            <span className="text-4xl font-bold">
                              {Math.round((subjects.reduce((acc, s) => acc + s.attendedClasses, 0) / Math.max(subjects.reduce((acc, s) => acc + s.totalClasses, 0), 1)) * 100)}%
                            </span>
                            <span className="text-sm text-gray-500">de presença</span>
                          </div>
                          <Progress value={(subjects.reduce((acc, s) => acc + s.attendedClasses, 0) / Math.max(subjects.reduce((acc, s) => acc + s.totalClasses, 0), 1)) * 100} />
                          <p className="text-sm text-gray-500">
                            {subjects.reduce((acc, s) => acc + s.attendedClasses, 0)} de {subjects.reduce((acc, s) => acc + s.totalClasses, 0)} aulas
                          </p>
                        </div>
                      </CardContent>
                    </Card>

                    <Card>
                      <CardHeader className="pb-3">
                        <div className="flex items-center justify-between">
                          <CardTitle className="text-lg">Trabalhos</CardTitle>
                          <CheckCircle2 className="h-5 w-5 text-green-500" />
                        </div>
                      </CardHeader>
                      <CardContent>
                        <div className="space-y-2">
                          <div className="flex items-baseline gap-2">
                            <span className="text-4xl font-bold">
                              {Math.round((subjects.reduce((acc, s) => acc + s.completedAssignments, 0) / Math.max(subjects.reduce((acc, s) => acc + s.assignments, 0), 1)) * 100)}%
                            </span>
                            <span className="text-sm text-gray-500">concluídos</span>
                          </div>
                          <Progress value={(subjects.reduce((acc, s) => acc + s.completedAssignments, 0) / Math.max(subjects.reduce((acc, s) => acc + s.assignments, 0), 1)) * 100} />
                          <p className="text-sm text-gray-500">
                            {subjects.reduce((acc, s) => acc + s.completedAssignments, 0)} de {subjects.reduce((acc, s) => acc + s.assignments, 0)} trabalhos
                          </p>
                        </div>
                      </CardContent>
                    </Card>

                    <Card className="bg-gradient-to-br from-blue-50 to-purple-50">
                      <CardHeader className="pb-3">
                        <div className="flex items-center justify-between">
                          <CardTitle className="text-lg">Pontuação Geral</CardTitle>
                          <Award className="h-5 w-5 text-amber-500" />
                        </div>
                      </CardHeader>
                      <CardContent>
                        <div className="space-y-2">
                          <div className="flex items-baseline gap-2">
                            <span className="text-4xl font-bold">{calculateScore()}</span>
                            <span className="text-sm text-gray-500">/ 100 pontos</span>
                          </div>
                          <Progress value={calculateScore()} />
                          <p className="text-sm text-gray-500">Baseado em frequência e trabalhos</p>
                        </div>
                      </CardContent>
                    </Card>
                  </div>
                </div>

                {subjects.length > 0 && (
                  <div>
                    <div className="flex items-center justify-between mb-4">
                      <h3 className="text-xl font-bold">Meus Professores</h3>
                      <Button variant="ghost" onClick={() => openTeacherModal()}>
                        Adicionar Professor
                      </Button>
                    </div>
                    <div className="grid md:grid-cols-3 gap-4">
                      {teachers.slice(0, 3).map((teacher) => (
                        <Card key={teacher.id}>
                          <CardHeader className="pb-3">
                            <div className="flex items-center gap-3">
                              <Avatar className="h-12 w-12">
                                <AvatarFallback>{teacher.name.charAt(0)}</AvatarFallback>
                              </Avatar>
                              <div>
                                <CardTitle className="text-base">Prof. {teacher.name}</CardTitle>
                                <CardDescription className="text-sm">{teacher.subject}</CardDescription>
                              </div>
                            </div>
                          </CardHeader>
                          <CardContent>
                            <div className="flex items-center gap-2 text-sm text-gray-500">
                              <Mail className="h-4 w-4" />
                              <span className="truncate">{teacher.email}</span>
                            </div>
                          </CardContent>
                          <CardFooter className="pt-3 gap-2">
                            <Button variant="outline" size="sm" className="flex-1">
                              <Mail className="h-4 w-4 mr-2" />
                              Contatar
                            </Button>
                            <Button variant="ghost" size="icon" onClick={() => openTeacherModal(teacher)}>
                              <Edit className="h-4 w-4" />
                            </Button>
                          </CardFooter>
                        </Card>
                      ))}
                    </div>
                  </div>
                )}

                {subjects.length > 0 && (
                  <div>
                    <div className="flex items-center justify-between mb-4">
                      <h3 className="text-xl font-bold">Resumo das Matérias</h3>
                      <Button variant="ghost" onClick={() => setActiveTab("aulas")}>Ver Todas</Button>
                    </div>
                    <div className="grid md:grid-cols-2 gap-4">
                      {subjects.slice(0, 4).map((subject) => (
                        <Card key={subject.id}>
                          <CardHeader className="pb-3">
                            <div className="flex items-center justify-between">
                              <div className="flex items-center gap-2">
                                <div className={cn("h-3 w-3 rounded-full", subject.color)} />
                                <CardTitle className="text-lg">{subject.name}</CardTitle>
                              </div>
                              <Badge variant="outline">Nota: {subject.testGrade}</Badge>
                            </div>
                            <CardDescription>Prof. {subject.teacher}</CardDescription>
                          </CardHeader>
                          <CardContent>
                            <div className="space-y-2 text-sm">
                              <div className="flex justify-between">
                                <span className="text-gray-600">Frequência:</span>
                                <span className="font-medium">{subject.attendedClasses}/{subject.totalClasses}</span>
                              </div>
                              <div className="flex justify-between">
                                <span className="text-gray-600">Trabalhos:</span>
                                <span className="font-medium">{subject.completedAssignments}/{subject.assignments}</span>
                              </div>
                            </div>
                          </CardContent>
                        </Card>
                      ))}
                    </div>
                  </div>
                )}
              </TabsContent>

              {/* AULAS */}
              <TabsContent value="aulas" className="space-y-6 mt-0">
                <div className="bg-gradient-to-r from-emerald-600 to-cyan-600 rounded-2xl p-8 text-white">
                  <div className="flex items-center justify-between">
                    <div>
                      <h2 className="text-3xl font-bold mb-2">Minhas Aulas</h2>
                      <p className="text-white/90">Acompanhe suas matérias, presenças, trabalhos e notas em um só lugar.</p>
                    </div>
                    <Button className="bg-white text-emerald-700 hover:bg-white/90" onClick={() => openSubjectModal()}>
                      <Plus className="h-4 w-4 mr-2" />
                      Nova Matéria
                    </Button>
                  </div>
                </div>

                <div>
                  <h3 className="text-2xl font-bold mb-4">Todas as Matérias</h3>
                  {subjects.length === 0 ? (
                    <Card className="p-12">
                      <div className="text-center space-y-4">
                        <BookOpen className="h-16 w-16 mx-auto text-gray-400" />
                        <h3 className="text-xl font-semibold">Nenhuma matéria cadastrada</h3>
                        <p className="text-gray-500">Comece adicionando suas matérias para acompanhar seu progresso</p>
                        <Button onClick={() => openSubjectModal()}>
                          <Plus className="h-4 w-4 mr-2" />
                          Adicionar Primeira Matéria
                        </Button>
                      </div>
                    </Card>
                  ) : (
                    <div className="space-y-4">
                      {subjects.map((subject) => (
                        <Card key={subject.id}>
                          <CardHeader>
                            <div className="flex items-center justify-between">
                              <div className="flex items-center gap-4">
                                <div className={cn("h-12 w-12 rounded-xl flex items-center justify-center text-white", subject.color)}>
                                  <BookOpen className="h-6 w-6" />
                                </div>
                                <div>
                                  <CardTitle className="text-xl">{subject.name}</CardTitle>
                                  <CardDescription>Prof. {subject.teacher}</CardDescription>
                                </div>
                              </div>
                              <Badge className="text-lg px-4 py-1">Nota: {subject.testGrade}</Badge>
                            </div>
                          </CardHeader>
                          <CardContent>
                            <div className="grid md:grid-cols-3 gap-6">
                              <div className="space-y-2">
                                <div className="flex items-center justify-between text-sm">
                                  <span className="font-medium">Frequência</span>
                                  <span className="text-gray-600">{Math.round((subject.attendedClasses / Math.max(subject.totalClasses, 1)) * 100)}%</span>
                                </div>
                                <Progress value={(subject.attendedClasses / Math.max(subject.totalClasses, 1)) * 100} />
                                <p className="text-xs text-gray-500">{subject.attendedClasses} de {subject.totalClasses} aulas</p>
                              </div>
                              <div className="space-y-2">
                                <div className="flex items-center justify-between text-sm">
                                  <span className="font-medium">Trabalhos</span>
                                  <span className="text-gray-600">{Math.round((subject.completedAssignments / Math.max(subject.assignments, 1)) * 100)}%</span>
                                </div>
                                <Progress value={(subject.completedAssignments / Math.max(subject.assignments, 1)) * 100} />
                                <p className="text-xs text-gray-500">{subject.completedAssignments} de {subject.assignments} concluídos</p>
                              </div>
                              <div className="space-y-2">
                                <div className="flex items-center justify-between text-sm">
                                  <span className="font-medium">Desempenho</span>
                                  <span className="text-gray-600">{subject.testGrade}/10</span>
                                </div>
                                <Progress value={subject.testGrade * 10} />
                                <p className="text-xs text-gray-500">Média das provas</p>
                              </div>
                            </div>
                          </CardContent>
                          <CardFooter className="gap-2 bg-gray-50">
                            <Button variant="secondary" className="flex-1">Ver Detalhes</Button>
                            <Button variant="outline">Registrar Presença</Button>
                            <Button variant="outline" size="icon" onClick={() => openSubjectModal(subject)}>
                              <Edit className="h-4 w-4" />
                            </Button>
                            <Button variant="outline" size="icon" className="text-red-500" onClick={() => deleteSubject(subject.id)}>
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          </CardFooter>
                        </Card>
                      ))}
                    </div>
                  )}
                </div>
              </TabsContent>

              {/* PROFESSORES */}
              <TabsContent value="professores" className="space-y-6 mt-0">
                <div className="bg-gradient-to-r from-violet-600 to-fuchsia-600 rounded-2xl p-8 text-white">
                  <div className="flex items-center justify-between">
                    <div>
                      <h2 className="text-3xl font-bold mb-2">Meus Professores</h2>
                      <p className="text-white/90">Gerencie os contatos e informações dos seus professores.</p>
                    </div>
                    <Button className="bg-white text-purple-700 hover:bg-white/90" onClick={() => openTeacherModal()}>
                      <UserPlus className="h-4 w-4 mr-2" />
                      Adicionar Professor
                    </Button>
                  </div>
                </div>

                <div>
                  <h3 className="text-2xl font-bold mb-4">Todos os Professores</h3>
                  {teachers.length === 0 ? (
                    <Card className="p-12">
                      <div className="text-center space-y-4">
                        <UserPlus className="h-16 w-16 mx-auto text-gray-400" />
                        <h3 className="text-xl font-semibold">Nenhum professor cadastrado</h3>
                        <p className="text-gray-500">Adicione professores para poder criar matérias</p>
                        <Button onClick={() => openTeacherModal()}>
                          <UserPlus className="h-4 w-4 mr-2" />
                          Adicionar Primeiro Professor
                        </Button>
                      </div>
                    </Card>
                  ) : (
                    <div className="grid md:grid-cols-3 gap-4">
                      {teachers.map((teacher) => (
                        <Card key={teacher.id}>
                          <CardHeader className="pb-3">
                            <div className="flex items-center gap-3">
                              <Avatar className="h-12 w-12">
                                <AvatarFallback>{teacher.name.charAt(0)}</AvatarFallback>
                              </Avatar>
                              <div>
                                <CardTitle className="text-lg">Prof. {teacher.name}</CardTitle>
                                <CardDescription>{teacher.subject}</CardDescription>
                              </div>
                            </div>
                          </CardHeader>
                          <CardContent>
                            <div className="flex items-center gap-2 text-sm text-gray-500">
                              <Mail className="h-4 w-4" />
                              <span className="truncate">{teacher.email}</span>
                            </div>
                          </CardContent>
                          <CardFooter className="gap-2">
                            <Button variant="outline" size="sm" className="flex-1">
                              <Mail className="h-4 w-4 mr-2" />
                              Contatar
                            </Button>
                            <Button variant="ghost" size="icon" onClick={() => openTeacherModal(teacher)}>
                              <Edit className="h-4 w-4" />
                            </Button>
                            <Button variant="ghost" size="icon" className="text-red-500" onClick={() => deleteTeacher(teacher.id)}>
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          </CardFooter>
                        </Card>
                      ))}
                    </div>
                  )}
                </div>
              </TabsContent>

              {/* ANOTAÇÕES */}
              <TabsContent value="anotacoes" className="space-y-6 mt-0">
                <div className="bg-gradient-to-r from-amber-600 to-red-600 rounded-2xl p-8 text-white">
                  <div className="flex items-center justify-between">
                    <div>
                      <h2 className="text-3xl font-bold mb-2">Minhas Anotações</h2>
                      <p className="text-white/90">Organize e guarde todas as suas anotações de estudo.</p>
                    </div>
                    <Button className="bg-white text-orange-700 hover:bg-white/90" onClick={() => openNoteModal()}>
                      <Plus className="h-4 w-4 mr-2" />
                      Nova Anotação
                    </Button>
                  </div>
                </div>

                <div>
                  <div className="flex items-center gap-2 mb-4">
                    <Button variant="outline" size="sm">Todas</Button>
                    {subjects.slice(0, 4).map((s) => (
                      <Button key={s.id} variant="outline" size="sm">{s.name}</Button>
                    ))}
                  </div>

                  <h3 className="text-2xl font-bold mb-4">Todas as Anotações</h3>
                  {notes.length === 0 ? (
                    <Card className="p-12">
                      <div className="text-center space-y-4">
                        <FileText className="h-16 w-16 mx-auto text-gray-400" />
                        <h3 className="text-xl font-semibold">Nenhuma anotação ainda</h3>
                        <p className="text-gray-500">Comece criando sua primeira anotação</p>
                        <Button onClick={() => openNoteModal()}>
                          <Plus className="h-4 w-4 mr-2" />
                          Criar Primeira Anotação
                        </Button>
                      </div>
                    </Card>
                  ) : (
                    <div className="grid md:grid-cols-3 gap-4">
                      {notes.map((note) => (
                        <Card key={note.id} className={cn("border-2", note.color)}>
                          <CardHeader className="pb-3">
                            <div className="flex items-center justify-between mb-2">
                              <Badge variant="outline">{note.subject}</Badge>
                              <span className="text-xs text-gray-500">{note.date}</span>
                            </div>
                            <CardTitle className="text-lg">{note.title}</CardTitle>
                          </CardHeader>
                          <CardContent>
                            <p className="text-sm text-gray-600 line-clamp-3">{note.content}</p>
                          </CardContent>
                          <CardFooter className="gap-2">
                            <Button variant="ghost" size="sm" className="flex-1">
                              <Eye className="h-4 w-4 mr-2" />
                              Ver
                            </Button>
                            <Button variant="ghost" size="icon" onClick={() => openNoteModal(note)}>
                              <Edit className="h-4 w-4" />
                            </Button>
                            <Button variant="ghost" size="icon" className="text-red-500" onClick={() => deleteNote(note.id)}>
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          </CardFooter>
                        </Card>
                      ))}
                    </div>
                  )}
                </div>
              </TabsContent>

              {/* PERFIL */}
              <TabsContent value="perfil" className="space-y-6 mt-0">
                <div className="bg-gradient-to-r from-violet-600 to-fuchsia-600 rounded-2xl p-8 text-white">
                  <div className="flex items-center gap-6">
                    <Avatar className="h-24 w-24 border-4 border-white/20">
                      <AvatarFallback className="text-3xl">{student?.name?.charAt(0) || "E"}</AvatarFallback>
                    </Avatar>
                    <div>
                      <h2 className="text-3xl font-bold mb-1">{student?.name || "Estudante"}</h2>
                      <p className="text-white/90 mb-2">{student?.email}</p>
                      <Badge className="bg-white/20">Conta Ativa</Badge>
                    </div>
                  </div>
                </div>

                <div className="grid md:grid-cols-2 gap-6">
                  <Card>
                    <CardHeader>
                      <CardTitle>Informações Pessoais</CardTitle>
                      <CardDescription>Gerencie suas informações pessoais</CardDescription>
                    </CardHeader>
                    <CardContent className="space-y-4">
                      <div className="space-y-2">
                        <Label>Nome Completo</Label>
                        <Input 
                          value={profileForm.nome} 
                          onChange={(e) => setProfileForm({...profileForm, nome: e.target.value})}
                          disabled={!profileEditing}
                        />
                      </div>
                      <div className="space-y-2">
                        <Label>Email</Label>
                        <Input value={profileForm.email} disabled />
                      </div>
                      <div className="space-y-2">
                        <Label>Telefone</Label>
                        <Input 
                          value={profileForm.telefone} 
                          onChange={(e) => setProfileForm({...profileForm, telefone: e.target.value})}
                          disabled={!profileEditing}
                          placeholder="(11) 99999-9999"
                        />
                      </div>
                    </CardContent>
                    <CardFooter>
                      {!profileEditing ? (
                        <Button className="w-full" onClick={() => setProfileEditing(true)}>
                          <Edit className="h-4 w-4 mr-2" />
                          Editar Perfil
                        </Button>
                      ) : (
                        <div className="w-full flex gap-2">
                          <Button variant="outline" className="flex-1" onClick={() => setProfileEditing(false)}>
                            Cancelar
                          </Button>
                          <Button className="flex-1" onClick={saveProfile}>
                            <Save className="h-4 w-4 mr-2" />
                            Salvar Alterações
                          </Button>
                        </div>
                      )}
                    </CardFooter>
                  </Card>

                  <Card>
                    <CardHeader>
                      <CardTitle>Estatísticas</CardTitle>
                      <CardDescription>Seu desempenho geral</CardDescription>
                    </CardHeader>
                    <CardContent className="space-y-6">
                      <div className="flex items-center justify-between">
                        <span className="text-sm text-gray-600">Total de Matérias</span>
                        <span className="text-2xl font-bold">{subjects.length}</span>
                      </div>
                      <div className="flex items-center justify-between">
                        <span className="text-sm text-gray-600">Total de Professores</span>
                        <span className="text-2xl font-bold">{teachers.length}</span>
                      </div>
                      <div className="flex items-center justify-between">
                        <span className="text-sm text-gray-600">Total de Anotações</span>
                        <span className="text-2xl font-bold">{notes.length}</span>
                      </div>
                      <div className="space-y-2">
                        <div className="flex items-center justify-between">
                          <span className="text-sm text-gray-600">Pontuação Geral</span>
                          <span className="text-2xl font-bold">{calculateScore()}/100</span>
                        </div>
                        <Progress value={calculateScore()} />
                      </div>
                    </CardContent>
                  </Card>
                </div>

                <Card>
                  <CardHeader>
                    <CardTitle>Configurações da Conta</CardTitle>
                    <CardDescription>Gerencie sua conta e preferências</CardDescription>
                  </CardHeader>
                  <CardContent>
                    <Button variant="destructive" className="w-full" onClick={() => { authApi.logout(); window.location.href = '/login' }}>
                      Sair da Conta
                    </Button>
                  </CardContent>
                </Card>
              </TabsContent>
            </Tabs>
          </div>
        </main>
      </div>

      {/* Modal Professor */}
      <Dialog open={teacherModal} onOpenChange={setTeacherModal}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{editingTeacher ? "Editar Professor" : "Adicionar Professor"}</DialogTitle>
            <DialogDescription>
              {editingTeacher ? "Atualize as informações do professor" : "Adicione um novo professor ao sistema"}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Nome *</Label>
              <Input 
                placeholder="Nome do professor"
                value={teacherForm.nome} 
                onChange={(e) => setTeacherForm({...teacherForm, nome: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <Label>Matéria</Label>
              <Input 
                placeholder="Matéria que leciona"
                value={teacherForm.disciplina} 
                onChange={(e) => setTeacherForm({...teacherForm, disciplina: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <Label>Email *</Label>
              <Input 
                type="email"
                placeholder="email@exemplo.com"
                value={teacherForm.email} 
                onChange={(e) => setTeacherForm({...teacherForm, email: e.target.value})}
              />
            </div>
          </div>
          <div className="flex gap-2">
            <Button variant="outline" className="flex-1" onClick={() => setTeacherModal(false)}>
              Cancelar
            </Button>
            <Button className="flex-1" onClick={saveTeacher}>
              <Save className="h-4 w-4 mr-2" />
              Salvar
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Modal Matéria */}
      <Dialog open={subjectModal} onOpenChange={setSubjectModal}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editingSubject ? "Editar Matéria" : "Adicionar Matéria"}</DialogTitle>
            <DialogDescription>
              Preencha as informações da matéria, incluindo nota e trabalhos
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-6 py-4">
            <div>
              <h3 className="font-semibold mb-4">Informações Básicas</h3>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>Nome da Matéria *</Label>
                  <Input 
                    placeholder="Ex: Matemática"
                    value={subjectForm.nome} 
                    onChange={(e) => setSubjectForm({...subjectForm, nome: e.target.value})}
                  />
                </div>
                <div className="space-y-2">
                  <Label>Professor *</Label>
                  <Select 
                    value={subjectForm.professorId} 
                    onValueChange={(value) => setSubjectForm({...subjectForm, professorId: value})}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Selecione o professor" />
                    </SelectTrigger>
                    <SelectContent>
                      {teachers.map((teacher) => (
                        <SelectItem key={teacher.id} value={teacher.id}>
                          {teacher.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4 mt-4">
                <div className="space-y-2">
                  <Label>Cor da Matéria</Label>
                  <Select 
                    value={subjectForm.cor} 
                    onValueChange={(value) => setSubjectForm({...subjectForm, cor: value})}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {COLORS.map((color) => (
                        <SelectItem key={color.value} value={color.value}>
                          <div className="flex items-center gap-2">
                            <div className={cn("w-4 h-4 rounded-full", color.value)} />
                            {color.label}
                          </div>
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label>Nota da Prova</Label>
                  <Input 
                    type="number"
                    min="0"
                    max="10"
                    step="0.1"
                    placeholder="0.0"
                    value={subjectForm.notaProva} 
                    onChange={(e) => setSubjectForm({...subjectForm, notaProva: e.target.value})}
                  />
                </div>
              </div>
            </div>

            <div>
              <div className="flex items-center justify-between mb-4">
                <h3 className="font-semibold">Trabalhos</h3>
                <Button type="button" variant="outline" size="sm" onClick={addTrabalho}>
                  <Plus className="h-4 w-4 mr-2" />
                  Adicionar Trabalho
                </Button>
              </div>

              {subjectForm.trabalhos.length === 0 ? (
                <div className="text-center py-8 text-gray-500">
                  Nenhum trabalho adicionado
                </div>
              ) : (
                <div className="space-y-3">
                  {subjectForm.trabalhos.map((trabalho, index) => (
                    <Card key={index} className="p-4">
                      <div className="space-y-3">
                        <div className="flex items-center justify-between">
                          <h4 className="font-medium text-sm">Trabalho {index + 1}</h4>
                          <Button 
                            type="button"
                            variant="ghost" 
                            size="sm"
                            className="text-red-500 h-8"
                            onClick={() => removeTrabalho(index)}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                        
                        <div className="grid grid-cols-2 gap-3">
                          <div className="space-y-1">
                            <Label className="text-xs">Título *</Label>
                            <Input 
                              value={trabalho.titulo}
                              onChange={(e) => updateTrabalho(index, 'titulo', e.target.value)}
                              placeholder="Nome do trabalho"
                              className="h-9"
                            />
                          </div>
                          <div className="space-y-1">
                            <Label className="text-xs">Data de Entrega</Label>
                            <Input 
                              type="date"
                              value={trabalho.dataEntrega}
                              onChange={(e) => updateTrabalho(index, 'dataEntrega', e.target.value)}
                              className="h-9"
                            />
                          </div>
                        </div>

                        <div className="space-y-1">
                          <Label className="text-xs">Descrição</Label>
                          <Textarea 
                            value={trabalho.descricao}
                            onChange={(e) => updateTrabalho(index, 'descricao', e.target.value)}
                            placeholder="Descrição do trabalho (opcional)"
                            rows={2}
                            className="resize-none"
                          />
                        </div>

                        <div className="flex items-center space-x-2">
                          <Checkbox
                            id={`concluido-${index}`}
                            checked={trabalho.concluido}
                            onCheckedChange={(checked) => updateTrabalho(index, 'concluido', checked)}
                          />
                          <Label htmlFor={`concluido-${index}`} className="text-sm cursor-pointer">
                            Trabalho concluído
                          </Label>
                        </div>
                      </div>
                    </Card>
                  ))}
                </div>
              )}
            </div>
          </div>
          
          <div className="flex gap-2">
            <Button variant="outline" className="flex-1" onClick={() => setSubjectModal(false)}>
              Cancelar
            </Button>
            <Button className="flex-1" onClick={saveSubject}>
              <Save className="h-4 w-4 mr-2" />
              Salvar Matéria
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Modal Anotação */}
      <Dialog open={noteModal} onOpenChange={setNoteModal}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{editingNote ? "Editar Anotação" : "Nova Anotação"}</DialogTitle>
            <DialogDescription>
              {editingNote ? "Atualize sua anotação de estudo" : "Crie uma nova anotação de estudo"}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Título *</Label>
              <Input 
                placeholder="Título da anotação"
                value={noteForm.titulo} 
                onChange={(e) => setNoteForm({...noteForm, titulo: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <Label>Matéria</Label>
              <Select 
                value={noteForm.materiaId} 
                onValueChange={(value) => setNoteForm({...noteForm, materiaId: value})}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Selecione a matéria" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">Sem matéria</SelectItem>
                  {subjects.map((subject) => (
                    <SelectItem key={subject.id} value={subject.id}>
                      {subject.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Conteúdo *</Label>
              <Textarea 
                placeholder="Escreva sua anotação aqui..."
                rows={8}
                value={noteForm.conteudo} 
                onChange={(e) => setNoteForm({...noteForm, conteudo: e.target.value})}
              />
            </div>
          </div>
          <div className="flex gap-2">
            <Button variant="outline" className="flex-1" onClick={() => setNoteModal(false)}>
              Cancelar
            </Button>
            <Button className="flex-1" onClick={saveNote}>
              <Save className="h-4 w-4 mr-2" />
              Salvar
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  )
}